struct Buffer {
  const uint8_t *buf;
  size_t len;
};

ssize_t reader_callback(struct archive *a, void *client_data,
                        const void **block) {
  (void)a;
  struct Buffer *buffer = (struct Buffer *)client_data;
  *block = buffer->buf;
  ssize_t len = buffer->len;
  buffer->len = 0;
  fprintf(stderr, "reader_callback: returning %zd bytes\n", len);
  return len;
